CREATE TABLE reminders (
  id       INTEGER PRIMARY KEY,
  task_id  INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  kind     TEXT    NOT NULL,  -- 'due-today', 'overdue', 'weekly'
  period   TEXT    NOT NULL,  -- the due date, or the ISO week
  sent_at  TEXT    NOT NULL DEFAULT (datetime('now')),
  UNIQUE (task_id, kind, period)
);

-- Claim: 1 row inserted = send it; 0 = already sent.
INSERT OR IGNORE INTO reminders (task_id, kind, period) VALUES (?, ?, ?);
